 "content": "def transform(grid):
    from collections import Counter
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    # Treat contiguous bands of non-background rows as repeated pattern blocks.
    blocks = []
    r = 0
    while r < h:
        if all(v == bg for v in grid[r]):
            r += 1
            continue
        start = r
        while r < h and any(v != bg for v in grid[r]):
            r += 1
        blocks.append((start, r))
    # Repeated copies have matching heights; use the copy with the most
    # foreground cells as the reference and mark omitted/different cells in 1.
    for i, (a0, a1) in enumerate(blocks):
        for j in range(i + 1, len(blocks)):
            b0, b1 = blocks[j]
            if a1 - a0 != b1 - b0:
                continue
            a_count = sum(v != bg for row in grid[a0:a1] for v in row)
            b_count = sum(v != bg for row in grid[b0:b1] for v in row)
            if a_count >= b_count:
                ref0, copy0 = a0, b0
            else:
                ref0, copy0 = b0, a0
            for dr in range(a1 - a0):
                for c in range(w):
                    ref, cur = grid[ref0 + dr][c], grid[copy0 + dr][c]
                    if ref != cur:
                        if cur == bg or ref != bg:
                            out[copy0 + dr][c] = 1
    return out
